// ---- Pacifico Yokohama (1991): the InterContinental hotel's sail (140 m, OSM measured), the curved Conference Center (49 m) and
// the low convention block with the National Convention Hall's ribbed shell roof (form simplified), on the real footprints.
LANDMARKS.typacifico = {zh:'横滨国际和平会议场', en:'Pacifico Yokohama', cat:'new', r:100, h:140, lt:{m:1, c:'#fff0d8', k:0.55},
  build(){
    const g = new THREE.Group(), RH = D.typacifico.R.HALL, RT = D.typacifico.R.HOT, RC = D.typacifico.R.CONF;
    const POD = [], GL = [], WH = [], HG = [], CR = [], SH = [], CG = [];
    // the convention block (podium) on the whole HALL footprint
    tPrism(POD, RH, -3.5, 11.5, 1);
    tWalls(GL, scR(RH, 1.003), 1.5, 8.5);
    // Conference Center: curved glass block, white parapet and floor bands
    tPrism(CG, RC, 11.5, 47.0, 1);
    tWalls(WH, scR(RC, 1.004), 47.0, 49.0); tCap(WH, RC, 49.0);
    for (let y = 18; y < 46; y += 7) tWalls(WH, scR(RC, 1.006), y, y + 0.7);
    // hotel sail: vertex chunk (P1 P2 P5 P6) at 140 m, two wings falling along a quarter-ellipse to 46 m at their ends
    const P = RT, hS = s => 46 + 94*Math.sqrt(Math.max(0, 1 - s*s));
    const wing = (o0, o1, i0, i1) => {      // o0/i0 at the vertex side, o1/i1 at the far end
      const N = 14; let prev = null;
      for (let k = 0; k <= N; k++){ const s = k/N, O = [lerp(o0[0], o1[0], s), lerp(o0[1], o1[1], s)], I = [lerp(i0[0], i1[0], s), lerp(i0[1], i1[1], s)], h = hS(s);
        if (prev){ const [Op, Ip, hp] = prev;
          tq(HG, [Op[0], 11.5, Op[1]], [O[0], 11.5, O[1]], [O[0], h, O[1]], [Op[0], hp, Op[1]]);
          tq(HG, [Ip[0], 11.5, Ip[1]], [I[0], 11.5, I[1]], [I[0], h - 2, I[1]], [Ip[0], hp - 2, Ip[1]]);
          tq(WH, [Op[0], hp, Op[1]], [O[0], h, O[1]], [I[0], h - 2, I[1]], [Ip[0], hp - 2, Ip[1]]);
          tBeam(CR, [Op[0], hp + 0.6, Op[1]], [O[0], h + 0.6, O[1]], 1.0, 1.4);                      // the lit crest along the sail edge
          // horizontal floor lines on the sea (outer) face
          for (let y = 15; y < Math.min(h, hp) - 1; y += 3.3){ const n0 = [Op[0], y, Op[1]], n1 = [O[0], y, O[1]]; tBeam(WH, n0, n1, 0.35, 0.8); }
        }
        prev = [O, I, h];
      }
      tq(HG, [o1[0], 11.5, o1[1]], [i1[0], 11.5, i1[1]], [i1[0], hS(1) - 2, i1[1]], [o1[0], hS(1), o1[1]]);
    };
    wing(P[1], P[0], P[6], P[7]); wing(P[2], P[3], P[5], P[4]);
    const VC = [P[1], P[2], P[5], P[6]];
    tWalls(HG, VC, 11.5, 140); tCap(WH, VC, 140);
    tBox(CR, (P[1][0] + P[2][0])/2, 140, (P[1][1] + P[2][1])/2, 4, 0.8, 4, 0);
    // the shell roof of the hall over the free part of the block (south of the Conference Center, west of the hotel)
    const H0 = [-30, 4], RIM = [[-44, 58], [-26, 63], [-4, 52], [18, 37], [34, 22], [42, 12]], NR = 12, NS = 9;
    const rimAt = f => { const x = f*(RIM.length - 1), i = Math.min(RIM.length - 2, Math.floor(x)), t = x - i; return [lerp(RIM[i][0], RIM[i + 1][0], t), lerp(RIM[i][1], RIM[i + 1][1], t)]; };
    const sh = (f, r) => { const q = rimAt(f), x = lerp(H0[0], q[0], r), z = lerp(H0[1], q[1], r), fr = f*NR*2, cor = Math.abs(Math.cos(fr*PI/2)); return [x, 11.5 + (18 + 1.6*cor)*Math.sin(PI*Math.pow(r, 0.75))*(0.75 + 0.25*Math.sin(PI*f)) + 1.2*r, z]; };
    for (let i = 0; i < NR*2; i++) for (let j = 0; j < NS; j++){ const f0 = i/(NR*2), f1 = (i + 1)/(NR*2), r0 = j/NS, r1 = (j + 1)/NS;
      tq(SH, sh(f0, r0), sh(f1, r0), sh(f1, r1), sh(f0, r1)); }
    for (let i = 0; i <= NR*2; i++){ const f = i/(NR*2), q = sh(f, 1); tq(SH, [q[0], 11.5, q[2]], [q[0], q[1], q[2]], sh(Math.min(1, f + 1/(NR*2)), 1), [sh(Math.min(1, f + 1/(NR*2)), 1)[0], 11.5, sh(Math.min(1, f + 1/(NR*2)), 1)[2]]); }
    flush(g, POD, {c:'#d6d4cc', m:0, lc:'#fff0d8', lk:0.35}); flush(g, GL, {c:'#33424b', glow:'#ffd9a0', gk:0.35});
    flush(g, CG, {c:'#6f8a97', m:1, fh:5.0, cw:3.2}); flush(g, HG, {c:'#8fa6b2', m:1, fh:3.3, cw:3.6});
    flush(g, WH, '#ecede8'); flush(g, SH, {c:'#e6e4dc', m:0, lc:'#fff3df', lk:0.6}); flush(g, CR, {c:'#f4f4ee', glow:'#fff6e6', gk:1.2});
    return g;
  }};
SG_PLACES.push({type:'typacifico', lat:D.typacifico.lat, lon:D.typacifico.lon, rot:0});

// ---- Cosmo Clock 21 (1989; moved 1999 onto a taller base): 112.5 m, wheel 100 m, 60 gondolas, the digital clock in the hub
// and the lit spokes. The wheel turns in the plane of local x (the footprint's long axis, about north-south).
LANDMARKS.tycosmoclock = {zh:'横滨宇宙时钟21', en:'Cosmo Clock 21', cat:'new', r:58, h:112.5, lt:{m:0, c:'#9fd6ff', k:1.1, e:0.8, anim:'show', c2:'#ff86d6'},
  build(){
    const g = new THREE.Group(), HY = 61.8, RR = 50, ST = [], RIM = [], SP = [], GO = [], GW = [], DG = [], DK = [];
    const F = D.tycosmoclock.R.F;
    // base station (boarding platforms at ~8 m) on the footprint
    tPrism(ST, scR(F, 0.92), -2, 7.6, 1);
    tBox(ST, 0, 7.6, 0, 20, 0.6, 15, 0);
    // two A-frame legs (one each side of the wheel) to the hub
    for (const z of [-7.6, 7.6]) for (const x of [-24, 24]) tBeam(ST, [x, 0, z], [0, HY, z*0.55], 1.6, 1.9);
    for (const z of [-7.6, 7.6]) tBeam(ST, [-17, 18, z*0.92], [17, 18, z*0.92], 1.0);
    tBeam(ST, [0, HY, -5.2], [0, HY, 5.2], 5.4); tBeam(ST, [0, HY, -6.5], [0, HY, 6.5], 2.0);
    // rims (two rings 6.4 m apart), lacing, spokes
    const NP = 120;
    for (let i = 0; i < NP; i++){ const a0 = i/NP*2*PI, a1 = (i + 1)/NP*2*PI;
      for (const z of [-3.2, 3.2]) tBeam(RIM, [Math.cos(a0)*RR, HY + Math.sin(a0)*RR, z], [Math.cos(a1)*RR, HY + Math.sin(a1)*RR, z], 1.1);
      tBeam(RIM, [Math.cos(a0)*RR, HY + Math.sin(a0)*RR, -3.2], [Math.cos(a1)*RR, HY + Math.sin(a1)*RR, 3.2], 0.35);
      if (i % 2 === 0) tBeam(RIM, [Math.cos(a0)*RR, HY + Math.sin(a0)*RR, -3.2], [Math.cos(a0)*RR, HY + Math.sin(a0)*RR, 3.2], 0.5);
      for (const z of [-3.2, 3.2]) tBeam(RIM, [Math.cos(a0)*(RR - 4), HY + Math.sin(a0)*(RR - 4), z*0.9], [Math.cos(a1)*(RR - 4), HY + Math.sin(a1)*(RR - 4), z*0.9], 0.45);
    }
    for (let i = 0; i < 60; i++){ const a = i/60*2*PI, b = a + PI/60;
      for (const z of [-3.2, 3.2]){ tBeam(SP, [Math.cos(a)*5.5, HY + Math.sin(a)*5.5, z*0.8], [Math.cos(a)*(RR - 0.6), HY + Math.sin(a)*(RR - 0.6), z], 0.28); tBeam(SP, [Math.cos(b)*5.5, HY + Math.sin(b)*5.5, z*0.8], [Math.cos(b)*(RR - 4), HY + Math.sin(b)*(RR - 4), z*0.9], 0.2); }
      // gondola hanging from its pivot on the rim
      const px = Math.cos(a)*RR, py = HY + Math.sin(a)*RR;
      tBox(GO, px, py - 3.9, 0, 2.6, 3.0, 2.3, 0); tBox(GO, px, py - 0.9, 0, 1.0, 0.9, 0.4, 0);
      tBox(GW, px, py - 3.0, 0, 2.7, 1.3, 2.4, 0);
    }
    // the clock: a dark disc in the hub on both faces, the time in seven-segment digits (time digits only)
    for (const z of [-3.9, 3.9]){ const s = Math.sign(z);
      for (let i = 0; i < 40; i++){ const a0 = i/40*2*PI, a1 = (i + 1)/40*2*PI; tt(DK, [0, HY, z], [Math.cos(a0)*17, HY + Math.sin(a0)*17, z], [Math.cos(a1)*17, HY + Math.sin(a1)*17, z]); } }
    const now = new Date(Date.now() + 9*3600e3), hh = now.getUTCHours(), mm = now.getUTCMinutes(), digs = [Math.floor(hh/10), hh % 10, -1, Math.floor(mm/10), mm % 10];
    const SEG = [0x3f, 0x06, 0x5b, 0x4f, 0x66, 0x6d, 0x7d, 0x07, 0x7f, 0x6f], W = 3.6, Hd = 6.4, T = 0.7;
    for (const zf of [-4.0, 4.0]){ const s = Math.sign(zf); let x0 = -12.4;
      for (const dg of digs){
        if (dg < 0){ for (const yy of [-1.4, 1.4]) tBox(DG, s > 0 ? x0 + 0.5 : -(x0 + 0.5), HY + yy - 0.4, zf, 0.8, 0.8, 0.12, 0); x0 += 1.8; continue; }
        const m = SEG[dg], cx = x0 + W/2, put = (x, y, w, h) => tBox(DG, s > 0 ? cx + x : -(cx + x), HY + y - h/2, zf, w, h, 0.12, 0);
        if (m & 1) put(0, Hd/2, W, T); if (m & 2) put(W/2, Hd/4, T, Hd/2); if (m & 4) put(W/2, -Hd/4, T, Hd/2); if (m & 8) put(0, -Hd/2, W, T);
        if (m & 16) put(-W/2, -Hd/4, T, Hd/2); if (m & 32) put(-W/2, Hd/4, T, Hd/2); if (m & 64) put(0, 0, W, T);
        x0 += W + 1.4; }
    }
    flush(g, ST, {c:'#d8dadc', m:0, lc:'#ffe8cc', lk:0.25}); flush(g, RIM, {c:'#eef2f6', m:0, lc:'#9fd6ff', lk:1.3}); flush(g, SP, {c:'#e8eef4', glow:'#bfe6ff', gk:0.9});
    flush(g, GO, {c:'#f1f1ee', m:0, lc:'#ffffff', lk:0.35}); flush(g, GW, {c:'#46606c', glow:'#ffe2b0', gk:0.25}); flush(g, DK, '#1d2328'); flush(g, DG, {c:'#cfe8ff', glow:'#d8f0ff', gk:1.8});
    return g;
  }};
SG_PLACES.push({type:'tycosmoclock', lat:D.tycosmoclock.lat, lon:D.tycosmoclock.lon, rot:D.tycosmoclock.rot});

// ---- Yokohama Red Brick Warehouses: No. 2 (1911, ~149 m) and No. 1 (1913, ~76 m), on their real footprints. Red brick with
// light stone bands, three storeys of small iron-shuttered windows in stone surrounds, a low grey gable roof, and the iron
// verandas (balconies on iron posts with pent roofs) on the side facing the event plaza between them.
function redbrick(R, vside){
  const g = new THREE.Group(), BR = [], ST = [], WF = [], WD = [], RF = [], IR = [];
  let xs = Infinity, xe = -Infinity; for (const p of R){ xs = Math.min(xs, p[0]); xe = Math.max(xe, p[0]); }
  const zN = -11.3, zS = 11.2, EAV = 15.6, RISE = 3.4;
  tPrism(BR, R, -2.5, EAV, 0); tCap(RF, R, EAV);
  for (const [y, h] of [[-2.5, 3.7], [5.1, 0.45], [10.3, 0.45], [EAV - 0.5, 0.7]]) tWalls(ST, scR(R, 1.004), y, y + h);
  // roof: gable over the rectangular part, ridge along x
  const xr0 = Math.max(xs, R.length > 4 ? -62 : xs);
  tGable(RF, (xr0 + xe)/2, EAV + 0.2, 0, xe - xr0, zS - zN, RISE, 0, 0.5);
  for (let x = xr0 + 6; x < xe - 4; x += 12) tBox(RF, x, EAV + RISE - 0.4, 0, 2.2, 1.0, 1.4, 0);
  // windows on the long sides (and ends), three floors, bays every 4.4 m
  const win = (x, y, z, n) => { tBox(WF, x, y - 0.25, z + n*0.08, 1.9, 2.9, 0.3, 0); tBox(WD, x, y, z + n*0.16, 1.35, 2.35, 0.3, 0); };
  for (const [z, n] of [[zN, -1], [zS, 1]]) for (let x = xs + 4; x < xe - 2.5; x += 4.4){
    if (z === zN && x < -62 && R.length > 4) continue;
    for (const y of [1.6, 6.6, 11.6]) win(x, y, z, n); }
  for (const x of [xs, xe]){ if (x === xs && R.length > 4) continue; for (let z = -6.6; z <= 6.7; z += 4.4) for (const y of [1.6, 6.6, 11.6]) { tBox(WF, x + Math.sign(x)*0.08, y - 0.25, z, 0.3, 2.9, 1.9, 0); tBox(WD, x + Math.sign(x)*0.16, y, z, 0.3, 2.35, 1.35, 0); } }
  // the iron veranda along one long side: posts, two balcony floors, railings and pent roofs
  const zv = vside > 0 ? zS : zN, zo = zv + vside*2.1, xv0 = xs + 3, xv1 = xe - 3;
  for (let x = xv0; x <= xv1 + 0.1; x += 4.4) tBox(IR, x, 0, zo, 0.4, EAV - 0.4, 0.4, 0);
  for (const y of [5.0, 10.2]){
    tBox(IR, (xv0 + xv1)/2, y - 0.2, zv + vside*1.05, xv1 - xv0, 0.45, 2.1, 0);
    tBox(IR, (xv0 + xv1)/2, y + 1.05, zo, xv1 - xv0, 0.16, 0.16, 0); tBox(IR, (xv0 + xv1)/2, y + 0.25, zo, xv1 - xv0, 0.9, 0.04, 0); tBox(IR, (xv0 + xv1)/2, y + 0.5, zo, xv1 - xv0, 0.08, 0.08, 0);
    for (let x = xv0; x < xv1; x += 1.1) tBox(IR, x, y + 0.25, zo, 0.05, 0.8, 0.05, 0);
  }
  for (const y of [4.6, 9.8, EAV - 0.6]){ const a = [xv0 - 0.4, y + 0.9, zv], b = [xv1 + 0.4, y + 0.9, zv], c = [xv1 + 0.4, y + 0.3, zo + vside*0.3], d = [xv0 - 0.4, y + 0.3, zo + vside*0.3]; tq(RF, a, b, c, d); }
  flush(g, BR, {c:'#a3523a', m:0, lc:'#ffc48a', lk:0.95, e:0.4}); flush(g, ST, {c:'#ded6c6', m:0, lc:'#ffd4a0', lk:0.9});
  flush(g, WF, '#e2dccf'); flush(g, WD, {c:'#2f3a36', glow:'#ffcf8a', gk:0.55}); flush(g, RF, '#5d6163'); flush(g, IR, '#30353a');
  return g;
}
LANDMARKS.tyredbrick = {zh:'横滨红砖仓库', en:'Yokohama Red Brick Warehouse', cat:'old', r:80, h:19.2, lt:{m:0, c:'#ffc48a', k:0.9}, build(){ return redbrick(D.tyredbrick.R.W2, 1); }};
LANDMARKS.tyredbrick_b = {zh:'横滨红砖仓库1号馆', en:'Red Brick Warehouse No. 1', cat:'old', r:44, h:19.2, label:false, lt:{m:0, c:'#ffc48a', k:0.9}, build(){ return redbrick(D.tyredbrick_b.R.W1, -1); }};
