// ---- Osanbashi Pier with the Yokohama International Passenger Terminal (2002): the ~480 m pier and the ~430 x 70 m terminal,
// 15 m at most, whose roof is a public plaza: an undulating timber deck with lawns, ramping down to the city end (local -x).
LANDMARKS.tyosanbashi = {zh:'横滨港大栈桥国际客船码头', en:'Osanbashi Pier', cat:'new', r:262, h:16, lt:{m:0, c:'#ffe2b8', k:0.45},
  build(){
    const g = new THREE.Group(), b0 = BASE(), y = a => a - b0, DECK = 2.9;
    const PR = D.tyosanbashi.R.PIER, TR = D.tyosanbashi.R.TERM, PI_ = [], TW = [], TW2 = [], TL = [], GL = [], BO = [], LM = [];
    tPrism(PI_, PR, y(-1.6), y(DECK), 1);
    // bollards and fenders along the pier edges
    for (const [a, b] of [[PR[0], PR[3]], [PR[1], PR[2]]]){ const L = Math.hypot(b[0] - a[0], b[1] - a[1]);
      for (let s = 10; s < L - 5; s += 18){ const x = lerp(a[0], b[0], s/L), z = lerp(a[1], b[1], s/L), zi = z + (z < 0 ? 1.0 : -1.0); tBox(BO, x, y(DECK), zi, 0.6, 0.7, 0.6, 0); tBox(BO, x, y(-0.8), z + (z < 0 ? -0.3 : 0.3), 1.6, 2.8, 0.5, 0); } }
    // width of the terminal outline at x (between its long sides)
    const span = x => { let lo = Infinity, hi = -Infinity; for (let i = 0; i < TR.length; i++){ const a = TR[i], b = TR[(i + 1) % TR.length];
      if ((a[0] - x)*(b[0] - x) <= 0 && a[0] !== b[0]){ const z = lerp(a[1], b[1], (x - a[0])/(b[0] - a[0])); lo = Math.min(lo, z); hi = Math.max(hi, z); } } return [lo, hi]; };
    const X0 = -221.8, X1 = 203.4, NX = 72, NF = 10;
    const env = x => { if (x < -150) return Math.max(0.6, 12.6*(x - X0)/(-150 - X0)); return Math.min(15.0, 12.4 + 1.6*Math.sin((x + 150)/355*2.6*PI) + 0.9*Math.sin((x + 150)/355*7*PI + 1)); };
    const H = (x, f) => DECK + env(x)*(0.8 + 0.2*Math.sin(PI*f)) + (x > -150 ? 0.7*Math.sin(f*3*PI + x/40) : 0);
    const lawn = (x, f) => f > 0.22 && f < 0.78 && ((x > -128 && x < -58) || (x > 40 && x < 118));
    let prev = null;
    for (let i = 0; i <= NX; i++){ const x = lerp(X0 + 0.4, X1 - 0.4, i/NX), [lo, hi] = span(x), col = [];
      for (let j = 0; j <= NF; j++){ const f = j/NF; col.push([x, y(H(x, f)), lerp(lo, hi, f)]); }
      if (prev){ for (let j = 0; j < NF; j++){ const xm = (x + prev[0][0])/2, fm = (j + 0.5)/NF; tq(lawn(xm, fm) ? TL : (i % 2 ? TW : TW2), prev[j], col[j], col[j + 1], prev[j + 1]); }
        // glazed side walls of the halls under the roof edge, and the sea-end wall
        for (const j of [0, NF]) tq(GL, [prev[j][0], y(DECK), prev[j][2]], [col[j][0], y(DECK), col[j][2]], col[j], prev[j]);
      }
      prev = col;
    }
    for (let j = 0; j < NF; j++) tq(GL, [prev[j][0], y(DECK), prev[j][2]], [prev[j + 1][0], y(DECK), prev[j + 1][2]], prev[j + 1], prev[j]);
    // roof-edge lamps (night)
    for (let i = 4; i < NX; i += 4){ const x = lerp(X0, X1, i/NX), [lo, hi] = span(x); for (const z of [lo + 1.5, hi - 1.5]) tBox(LM, x, y(H(x, z < 0 ? 0.03 : 0.97)), z, 0.3, 0.9, 0.3, 0); }
    flush(g, PI_, '#a5a39b'); flush(g, BO, '#3b3d3e'); flush(g, TW, {c:'#a99c88', m:0, lc:'#ffd9a8', lk:0.35}); flush(g, TW2, {c:'#9b8e7b', m:0, lc:'#ffd9a8', lk:0.35}); flush(g, TL, '#6f8c4c');
    flush(g, GL, {c:'#3e4c55', glow:'#ffe0b0', gk:0.5}); flush(g, LM, {c:'#ddd', glow:'#fff0d0', gk:1.4});
    return g;
  }};
SG_PLACES.push({type:'tyosanbashi', lat:D.tyosanbashi.lat, lon:D.tyosanbashi.lon, rot:D.tyosanbashi.rot});

// ---- Hikawa Maru (1930): 163.3 m x 20.1 m ocean liner, museum ship at Yamashita Park since 1961. Black hull with a red boot-top,
// white superstructure, one funnel (plain: no house marks), two masts and derrick posts; dressing lights from the bow over the
// masts to the stern at night. Bow = local +x (the footprint's pointed NE end); waterline at the sea surface.
LANDMARKS.tyhikawamaru = {zh:'冰川丸', en:'Hikawa Maru', cat:'old', r:88, h:36, lt:{m:0, c:'#ffe0b0', k:0.5},
  build(){
    const g = new THREE.Group(), b0 = BASE(), y = a => a - b0, RS = D.tyhikawamaru.R.SHIP;
    const HB = [], HR = [], DK = [], WS = [], WD = [], FN = [], FB = [], MS = [], LB = [], DL = [];
    // half-breadth at x from the footprint
    const hb = x => { let w = 0; for (let i = 0; i < RS.length; i++){ const a = RS[i], b = RS[(i + 1) % RS.length]; if ((a[0] - x)*(b[0] - x) <= 0 && a[0] !== b[0]){ const z = lerp(a[1], b[1], (x - a[0])/(b[0] - a[0])); w = Math.max(w, Math.abs(z)); } } return w; };
    const XS = -79.2, XB = 84.3, dk = x => { const t = Math.max(0, Math.min(1, (x - XS)/(XB - XS))); return 9.75 + (t < 0.5 ? 2.15*Math.pow(1 - 2*t, 2) : 2.45*Math.pow(2*t - 1, 2)); };
    const ST = []; for (let i = 0; i <= 40; i++){ const t = i/40, x = XS + (XB - XS)*(0.5 - 0.5*Math.cos(PI*t)); ST.push(x); }
    const sec = (x, top, bot) => { const b = Math.max(0.15, hb(x)), d = dk(x); const bt = Math.max(0.15, b*0.92);
      return top ? [[b, d + 1.0], [b, 0.9], [-b, 0.9], [-b, d + 1.0]] : [[bt, 0.9], [b*0.86, -3.5], [b*0.35, -6.5], [-b*0.35, -6.5], [-b*0.86, -3.5], [-bt, 0.9]]; };
    for (let i = 0; i < ST.length - 1; i++){ const x0 = ST[i], x1 = ST[i + 1];
      const A0 = sec(x0, true), A1 = sec(x1, true); tq(HB, [x0, y(A0[0][1]), A0[0][0]], [x1, y(A1[0][1]), A1[0][0]], [x1, y(A1[1][1]), A1[1][0]], [x0, y(A0[1][1]), A0[1][0]]);
      tq(HB, [x0, y(A0[3][1]), A0[3][0]], [x1, y(A1[3][1]), A1[3][0]], [x1, y(A1[2][1]), A1[2][0]], [x0, y(A0[2][1]), A0[2][0]]);
      const B0 = sec(x0, false), B1 = sec(x1, false); for (let k = 0; k < B0.length - 1; k++) tq(HR, [x0, y(B0[k][1]), B0[k][0]], [x1, y(B1[k][1]), B1[k][0]], [x1, y(B1[k + 1][1]), B1[k + 1][0]], [x0, y(B0[k + 1][1]), B0[k + 1][0]]);
      const b0w = Math.max(0.15, hb(x0)) - 0.4, b1w = Math.max(0.15, hb(x1)) - 0.4; tq(DK, [x0, y(dk(x0)), b0w], [x1, y(dk(x1)), b1w], [x1, y(dk(x1)), -b1w], [x0, y(dk(x0)), -b0w]);
      // the inside of the bulwark
      for (const s of [1, -1]) tq(HB, [x0, y(dk(x0)), s*b0w], [x1, y(dk(x1)), s*b1w], [x1, y(dk(x1) + 1.0), s*(b1w + 0.4)], [x0, y(dk(x0) + 1.0), s*(b0w + 0.4)]);
    }
    tq(HB, [XS, y(dk(XS) + 1), hb(XS + 0.3)], [XS, y(dk(XS) + 1), -hb(XS + 0.3)], [XS, y(0.9), -hb(XS + 0.3)], [XS, y(0.9), hb(XS + 0.3)]);
    // superstructure: three white decks, the bridge, promenade glazing
    const D0 = 9.75;
    const tiers = [[-41, 34, 8.2, D0, 2.7], [-35, 28, 7.6, D0 + 2.7, 2.6], [-16, 26, 6.6, D0 + 5.3, 2.6], [17, 25, 6.0, D0 + 7.9, 2.6]];
    for (const [x0, x1, hw, yb, h] of tiers){ tBox(WS, (x0 + x1)/2, y(yb), 0, x1 - x0, h, 2*hw, 0); tBox(WD, (x0 + x1)/2, y(yb + h*0.35), 0, x1 - x0 - 1.2, h*0.42, 2*hw + 0.12, 0); tBox(WS, (x0 + x1)/2, y(yb + h - 0.15), 0, x1 - x0 + 1.4, 0.3, 2*hw + 1.6, 0); }
    tBox(WS, 46, y(dk(46)), 0, 14, 2.6, 13, 0); tBox(WS, -58, y(dk(-58)), 0, 12, 2.4, 12, 0);
    // funnel (oval), plain black top over a buff body
    const fx = -3.5; for (let i = 0; i < 16; i++){ const a0 = i/16*2*PI, a1 = (i + 1)/16*2*PI, p0 = [fx + Math.cos(a0)*4.6, Math.sin(a0)*3.3], p1 = [fx + Math.cos(a1)*4.6, Math.sin(a1)*3.3];
      tq(FB, [p0[0], y(D0 + 7.9), p0[1]], [p1[0], y(D0 + 7.9), p1[1]], [p1[0] - 0.5, y(26.2), p1[1]], [p0[0] - 0.5, y(26.2), p0[1]]);
      tq(FN, [p0[0] - 0.5, y(26.2), p0[1]], [p1[0] - 0.5, y(26.2), p1[1]], [p1[0] - 0.7, y(28.6), p1[1]], [p0[0] - 0.7, y(28.6), p0[1]]); }
    tBox(FN, fx - 0.6, y(28.4), 0, 8.4, 0.2, 5.6, 0);
    // masts, derrick posts and booms
    const masts = [[50, 36.5], [-54, 34.5]];
    for (const [x, top] of masts){ tBeam(MS, [x, y(dk(x)), 0], [x, y(top), 0], 0.6); tBeam(MS, [x - 3, y(top - 9), 0], [x + 3, y(top - 9), 0], 0.3); }
    for (const x of [38, 63, -44, -66]){ for (const z of [-3.2, 3.2]) tBeam(MS, [x, y(dk(x)), z], [x, y(dk(x) + 11), z], 0.5); tBeam(MS, [x, y(dk(x) + 11), -3.2], [x, y(dk(x) + 11), 3.2], 0.35);
      tBeam(MS, [x, y(dk(x) + 2), 1.5], [x + (x > 0 ? 9 : -9)*0.9, y(dk(x) + 6), 1.5], 0.3); }
    // lifeboats on the boat deck, both sides
    for (const s of [1, -1]) for (let x = -30; x <= 20; x += 7.2){ tBox(LB, x, y(D0 + 5.6), s*8.6, 6.4, 1.4, 2.0, 0); tBox(MS, x - 2.8, y(D0 + 5.3), s*8.0, 0.2, 2.6, 0.2, 0); tBox(MS, x + 2.8, y(D0 + 5.3), s*8.0, 0.2, 2.6, 0.2, 0); }
    // dressing lights: bow -> foremast -> mainmast -> stern
    const pts = [[XB - 0.5, dk(XB) + 1.5], [50, 36.0], [-54, 34.0], [XS + 0.6, dk(XS) + 1.5]];
    for (let k = 0; k < pts.length - 1; k++){ const a = pts[k], b = pts[k + 1], L = Math.hypot(b[0] - a[0], b[1] - a[1]), n = Math.round(L/2.6);
      for (let i = 0; i <= n; i++){ const t = i/n, x = lerp(a[0], b[0], t), yy = lerp(a[1], b[1], t) - 2.2*Math.sin(PI*t); tBox(DL, x, y(yy), 0, 0.35, 0.35, 0.35, 0); } }
    for (const s of [1, -1]) for (let x = -38; x <= 32; x += 3) tBox(DL, x, y(D0 + 2.55), s*8.3, 0.25, 0.25, 0.25, 0);
    flush(g, HB, '#1d1e21'); flush(g, HR, '#7c2a22'); flush(g, DK, '#9b8463'); flush(g, WS, {c:'#efefea', m:0, lc:'#ffe6c0', lk:0.55});
    flush(g, WD, {c:'#343b40', glow:'#ffd596', gk:0.5}); flush(g, FB, '#d8c8a4'); flush(g, FN, '#18191b'); flush(g, MS, '#d9d6cc'); flush(g, LB, '#f2efe6');
    flush(g, DL, {c:'#fff2d0', glow:'#ffe2a0', gk:2.0});
    return g;
  }};
SG_PLACES.push({type:'tyhikawamaru', lat:D.tyhikawamaru.lat, lon:D.tyhikawamaru.lon, rot:D.tyhikawamaru.rot});

// ---- Yokohama Marine Tower (1961): 106 m, ten-sided steel lattice (silver) around an olive-brown core, the observation deck at
// about 100 m in a drum near the top, the old lighthouse lantern and mast; on its round two-storey base building.
LANDMARKS.tymarinetower = {zh:'横滨海洋塔', en:'Yokohama Marine Tower', cat:'old', r:34, h:106, lt:{m:0, c:'#e8f0ff', k:1.0, e:0.7},
  build(){
    const g = new THREE.Group(), PODR = D.tymarinetower.R.POD, PO = [], PG = [], LA = [], CO = [], OB = [], OG = [], AV = [];
    tPrism(PO, PODR, -3, 11.6, 1); tWalls(PG, scR(PODR, 1.004), 1.0, 9.6);
    tPrism(PO, D.tymarinetower.R.ANX, -3, 8.4, 1); tWalls(PG, scR(D.tymarinetower.R.ANX, 1.006, -16, -8), 1.0, 6.8);   // the low annex on the NW side
    const prof = [[0, 7.3], [12, 6.7], [24, 5.9], [40, 5.0], [60, 4.4], [78, 4.3], [86, 4.7], [91, 6.6]];
    const rAt = yy => { for (let i = 0; i < prof.length - 1; i++) if (yy <= prof[i + 1][0]){ const t = (yy - prof[i][0])/(prof[i + 1][0] - prof[i][0]); return lerp(prof[i][1], prof[i + 1][1], t); } return prof[prof.length - 1][1]; };
    const N = 10, P = (yy, i) => { const a = (i + 0.5)/N*2*PI, r = rAt(yy); return [Math.cos(a)*r, yy, Math.sin(a)*r]; };
    const LV = []; for (let yy = 11.6; yy < 91; yy += 5.8) LV.push(yy); LV.push(91);
    for (let k = 0; k < LV.length - 1; k++) for (let i = 0; i < N; i++){ const a = P(LV[k], i), b = P(LV[k + 1], i), c = P(LV[k], i + 1), d = P(LV[k + 1], i + 1);
      tBeam(LA, a, b, 0.7); tBeam(LA, a, c, 0.4); tBeam(LA, a, d, 0.28); tBeam(LA, c, b, 0.28); }
    for (let i = 0; i < N; i++) tBeam(LA, P(0, i), P(11.6, i), 0.9);
    LCyl(g, 2.5, 2.7, 80, 0, 11.6, 0, '#6d6650', 12);
    // observation deck drum (two levels), roof, lantern and mast
    tPrism(OB, Array.from({length:20}, (_, i) => [Math.cos(i/20*2*PI)*8.4, Math.sin(i/20*2*PI)*8.4]), 91, 92.2, 2);
    tPrism(OG, Array.from({length:20}, (_, i) => [Math.cos(i/20*2*PI)*8.2, Math.sin(i/20*2*PI)*8.2]), 92.2, 99.4, 0);
    tBox(OB, 0, 95.6, 0, 16.9, 0.5, 16.9, 0.0);
    tPrism(OB, Array.from({length:20}, (_, i) => [Math.cos(i/20*2*PI)*8.8, Math.sin(i/20*2*PI)*8.8]), 99.4, 100.6, 1);
    for (let i = 0; i < 20; i++){ const a = i/20*2*PI; tBox(OB, Math.cos(a)*8.3, 92.2, Math.sin(a)*8.3, 0.4, 7.2, 0.4, -a); }
    LCyl(g, 3.0, 3.6, 1.6, 0, 100.6, 0, '#c9cdd0', 16); LCyl(g, 1.9, 1.9, 2.4, 0, 102.2, 0, {c:'#7d9aa6', glow:'#f6fbff', gk:0.9}, 12);
    LCone(g, 2.2, 1.0, 0, 104.6, 0, '#c9cdd0', 12); LCyl(g, 0.15, 0.25, 0.9, 0, 105.1, 0, '#c9cdd0', 6); tBox(AV, 0, 105.7, 0, 0.5, 0.4, 0.5, 0);
    flush(g, PO, {c:'#e2e4e2', m:0, lc:'#eaf1ff', lk:0.5}); flush(g, PG, {c:'#3a4650', glow:'#ffe2b8', gk:0.45});
    flush(g, LA, {c:'#c4c9cd', m:0, lc:'#eaf2ff', lk:1.25}); flush(g, OB, '#cfd3d6'); flush(g, OG, {c:'#2f3c45', glow:'#ffe4bc', gk:0.7});
    flush(g, AV, {c:'#c22', glow:'#ff2a1a', gk:2.0});
    return g;
  }};
SG_PLACES.push({type:'tymarinetower', lat:D.tymarinetower.lat, lon:D.tymarinetower.lon, rot:0});

// ---- Yokohama Chinatown: SITE with the decorated paifang gates on their OSM roof footprints (pillars in the colours of the Four
// Symbols on the four direction gates: Choyo-mon east blue, Suzaku-mon south red, Enpei-mon west white, Genbu-mon north black),
// red lanterns strung over the main streets; the Kanteibyo (Guan Di temple) and the Mazu temple as landmarks (sub-keys, unlabelled).
// No shop names, no signs. The keep is a tiny triangle: the real Chinatown buildings stay.
function paifang(A, cx, y0, cz, L, W, H, ry, n4){
  // A = {P pillars, S stone, B beams, Q plaque, R roof, G gold}; local x along the gate (L), z across (W)
  const c = Math.cos(ry), s = Math.sin(ry), at = (x, z) => [cx + x*c + z*s, cz - x*s + z*c];
  const xs = n4 ? [-L*0.46, -L*0.16, L*0.16, L*0.46] : [-L*0.42, L*0.42];
  for (const x of xs){ const p = at(x, 0); tBox(A.P, p[0], y0, p[1], 0.55, H*0.8, 0.55, ry); tBox(A.S, p[0], y0, p[1], 0.95, 1.0, Math.max(1.1, W*0.55), ry); }
  const xm = xs[xs.length - 1] + 0.3;
  for (const [yy, hh] of [[H*0.56, 0.45], [H*0.68, 0.55]]){ const p = at(0, 0); tBox(A.B, p[0], y0 + yy, p[1], 2*xm, hh, 0.5, ry); }
  { const p = at(0, 0); tBox(A.Q, p[0], y0 + H*0.585, p[1], L*0.18, H*0.09, 0.62, ry); tBox(A.G, p[0], y0 + H*0.575, p[1], L*0.21, H*0.11, 0.56, ry); }
  // bracket bands and roofs: the centre roof highest, side roofs lower (four-pillar gates)
  const roof = (x, w, yb, h) => { const p = at(x, 0); tBox(A.G, p[0], y0 + yb - 0.5, p[1], w*0.9, 0.5, W*0.55, ry); tCnRoof(A.R, p[0], y0 + yb, p[1], w, W, h, ry, 0.7); };
  if (n4){ roof(0, L*0.48, H*0.84, H*0.16); roof(-L*0.33, L*0.3, H*0.74, H*0.12); roof(L*0.33, L*0.3, H*0.74, H*0.12); }
  else roof(0, L*1.0, H*0.82, H*0.18);
}
const CN_COL = {zenrin:'#b8262a', choyo:'#2f62a6', suzaku:'#c0262c', genbu:'#26282a', enpei:'#e6e3dc', tencho:'#b8262a', chikyu:'#b8262a', seiyo:'#b8262a'};
Object.assign(SITES, {tychinatown:{zh:'横滨中华街', en:'Yokohama Chinatown', lat:D.tychinatown.lat, lon:D.tychinatown.lon, r:312, keep:[[0, 0], [0.6, 0], [0, 0.6]], h:15,
  lt:{m:0, c:'#ffb070', k:0.8},
  build(ctx){
    const g = new THREE.Group(), GR = D.tychinatown.R, M = {};
    const mat = k => (M[k] = M[k] || []);
    for (const [k, R] of Object.entries(GR)){
      let cx, cz, L, W, ry;
      if (R.length === 2){ cx = (R[0][0] + R[1][0])/2; cz = (R[0][1] + R[1][1])/2; L = 6.0; W = 2.4; ry = -Math.atan2(R[1][1] - R[0][1], R[1][0] - R[0][0]); }
      else { cx = R.reduce((a, p) => a + p[0], 0)/4; cz = R.reduce((a, p) => a + p[1], 0)/4;
        const e1 = Math.hypot(R[1][0] - R[0][0], R[1][1] - R[0][1]), e2 = Math.hypot(R[2][0] - R[1][0], R[2][1] - R[1][1]);
        const [a, b] = e1 >= e2 ? [R[0], R[1]] : [R[1], R[2]]; L = Math.max(e1, e2); W = Math.min(e1, e2); ry = -Math.atan2(b[1] - a[1], b[0] - a[0]); }
      const H = Math.max(8, Math.min(14, 4 + 0.9*L)), y0 = Math.min(ctx.gy(cx, cz), ctx.gy(cx + 3, cz), ctx.gy(cx - 3, cz)) - 0.3;
      paifang({P:mat('P_' + k), S:mat('S'), B:mat('B'), Q:mat('Q'), R:mat('R'), G:mat('G')}, cx, y0, cz, L, Math.max(2.2, W), H, ry, L >= 6.4);
      ctx.lamp(cx, y0 + H*0.5, cz, [255, 190, 120]);
    }
    // Mazu temple's street gate (east edge of its precinct, on the Minami-mon Silk Road side)
    { const cx = 209.0, cz = 54.5, y0 = ctx.gy(cx, cz) - 0.3; paifang({P:mat('P_tencho'), S:mat('S'), B:mat('B'), Q:mat('Q'), R:mat('R'), G:mat('G')}, cx, y0, cz, 7.0, 2.6, 9.6, 0.169 + PI/2, true); }
    // red lanterns strung across the main streets
    const LN = mat('LN'), CB = mat('CB');
    const streets = [[[-138.9, -49.4], [161.8, -126.1]], [[211.1, 9.1], [-14.0, 48.3], [-111.7, 65.9]], [[183.0, -122.3], [247.5, 153.8]]];
    for (const S of streets) for (let i = 0; i < S.length - 1; i++){ const a = S[i], b = S[i + 1], Ls = Math.hypot(b[0] - a[0], b[1] - a[1]), ux = (b[0] - a[0])/Ls, uz = (b[1] - a[1])/Ls;
      for (let s = 9; s < Ls - 6; s += 11){ const x = a[0] + ux*s, z = a[1] + uz*s, yb = ctx.gy(x, z) + 6.4, nx = -uz*3.4, nz = ux*3.4;
        tBeam(CB, [x - nx, yb + 0.6, z - nz], [x, yb, z], 0.05); tBeam(CB, [x, yb, z], [x + nx, yb + 0.6, z + nz], 0.05);
        for (const f of [-0.6, 0, 0.6]){ const px = x + nx*f, pz = z + nz*f, py = yb + 0.6*Math.abs(f) - 0.9; tBox(LN, px, py, pz, 0.55, 0.75, 0.55, Math.atan2(uz, ux)); }
        if ((s/11 | 0) % 3 === 0) ctx.lamp(x, yb - 0.6, z, [255, 80, 60]); } }
    const COLS = {S:'#cfcac0', B:{c:'#2c6a5a', m:0, lc:'#ffc890', lk:0.7}, Q:'#1f3d6e', R:{c:'#2f7055', m:0, lc:'#ffc890', lk:0.6}, G:{c:'#c9a12c', m:0, lc:'#ffd890', lk:0.9},
      LN:{c:'#c8231c', glow:'#ff5a36', gk:1.3}, CB:'#3a3a3a'};
    for (const [k, A] of Object.entries(M)){ const col = k.startsWith('P_') ? {c:CN_COL[k.slice(2)], m:0, lc:'#ffc890', lk:0.8} : COLS[k]; flush(g, A, col); }
    return g;
  }}});

// Kanteibyo (Guan Di temple): stone platform with steps, red-pillared hall with gold panels, two-tier green-tiled roofs with gold
